#!/usr/bin/env bash
# Downloads the original page of every source in this collection (regenerated from the final file set) into ./originals/
# (raw HTML plus a plain-text rendering) for local reading. The folder is gitignored.
# Pages that block plain downloads (GameFAQs, GameSpot, MobyGames) are fetched from the
# Wayback Machine; iDNES needs a crawler user agent to get past its consent wall.
set -u
cd "$(dirname "$0")"
mkdir -p originals
UA='Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Safari/537.36'
BOT='Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)'
WB='https://web.archive.org/web/2id_/'
fetch() { # name url [user-agent]
  local name=$1 url=$2 ua=${3:-$UA}
  local code
  code=$(curl -sS -L -A "$ua" --max-time 90 -o "originals/$name.html" -w '%{http_code}' "$url")
  if [ "$code" != 200 ]; then  # blocked or gone: try the Wayback Machine's raw copy
    code="$code->$(curl -sS -L -A "$ua" --max-time 120 -o "originals/$name.html" -w '%{http_code}' "https://web.archive.org/web/2id_/$url")"
  fi
  printf '%-40s %s\n' "$name" "$code"
  if file "originals/$name.html" | grep -q PDF; then mv "originals/$name.html" "originals/$name.pdf"; command -v pdftotext >/dev/null && pdftotext -layout "originals/$name.pdf" "originals/$name.txt"
  elif command -v html2text >/dev/null; then html2text --body-width=0 --ignore-images "originals/$name.html" > "originals/$name.txt" 2>/dev/null; fi
  sleep 2
}
